CREATE TABLE marketing_plan (id VARCHAR(64) PRIMARY KEY,name VARCHAR(255) NOT NULL,status VARCHAR(32) NOT NULL,audience_id VARCHAR(64) NOT NULL,audience_version INT NOT NULL,created_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL);
CREATE TABLE flow_node (id BIGINT AUTO_INCREMENT PRIMARY KEY,plan_id VARCHAR(64) NOT NULL,node_key VARCHAR(64) NOT NULL,type VARCHAR(32) NOT NULL,name VARCHAR(255),config VARCHAR(2000),position_x INT NOT NULL,position_y INT NOT NULL,CONSTRAINT uk_plan_node UNIQUE(plan_id,node_key));
CREATE TABLE flow_edge (id BIGINT AUTO_INCREMENT PRIMARY KEY,plan_id VARCHAR(64) NOT NULL,source_node_key VARCHAR(64) NOT NULL,target_node_key VARCHAR(64) NOT NULL,branch_label VARCHAR(32));
